CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, email VARCHAR(255) UNIQUE NOT NULL, password VARCHAR(255) NOT NULL, name VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS accounts (id SERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL, institution VARCHAR(255), account_type VARCHAR(50), balance NUMERIC DEFAULT 0, currency VARCHAR(10) DEFAULT 'USD', account_number VARCHAR(50), status VARCHAR(50) DEFAULT 'active', created_by INTEGER REFERENCES users(id), created_at TIMESTAMP DEFAULT NOW(), updated_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS transactions (id SERIAL PRIMARY KEY, account_id INTEGER REFERENCES accounts(id) ON DELETE CASCADE, merchant VARCHAR(255), category VARCHAR(100), amount NUMERIC NOT NULL, transaction_type VARCHAR(50) DEFAULT 'debit', date DATE DEFAULT CURRENT_DATE, description TEXT, status VARCHAR(50) DEFAULT 'completed', created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS subscriptions (id SERIAL PRIMARY KEY, account_id INTEGER REFERENCES accounts(id) ON DELETE CASCADE, service_name VARCHAR(255), amount NUMERIC, frequency VARCHAR(50) DEFAULT 'monthly', next_charge DATE, status VARCHAR(50) DEFAULT 'active', category VARCHAR(100), detected_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS budgets (id SERIAL PRIMARY KEY, category VARCHAR(100), monthly_limit NUMERIC, spent NUMERIC DEFAULT 0, period VARCHAR(20) DEFAULT '2024-03', created_by INTEGER REFERENCES users(id), created_at TIMESTAMP DEFAULT NOW());
CREATE TABLE IF NOT EXISTS finance_logs (id SERIAL PRIMARY KEY, agent VARCHAR(100), action VARCHAR(255), status VARCHAR(50), message TEXT, duration_ms INTEGER, created_at TIMESTAMP DEFAULT NOW());
